import type { TooltipProps as CoreTooltipProps } from "../tooltip.types";

import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import {
  autoUpdate,
  flip,
  arrow,
  offset as floatingOffset,
  shift,
  hide,
  useDismiss,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
  useTransitionStyles,
  type Placement,
  type UseFloatingReturn,
} from "@floating-ui/react";
import { isNullish } from "@system";

export interface UseTooltipOptions {
  position?: Placement;
  enterDelay?: number;
  leaveDelay?: number;
  open?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  showOnHover?: boolean;
  offset?: number;
  arrow?: boolean;
  variant?: CoreTooltipProps["variant"];
  styleSlots?: CoreTooltipProps["styleSlots"];
}

export interface TooltipContextValue {
  arrowRef: React.RefObject<SVGSVGElement>;
  floatingStyles: UseFloatingReturn["floatingStyles"];
  floatingContext: UseFloatingReturn["context"];
  getReferenceProps: ReturnType<typeof useInteractions>["getReferenceProps"];
  getFloatingProps: ReturnType<typeof useInteractions>["getFloatingProps"];
  isMounted: boolean;
  refs: UseFloatingReturn["refs"];
  styles: React.CSSProperties;
  currentOpenState: boolean;
  actualPlacement: Placement;
  showArrow: boolean;
  middlewareData: UseFloatingReturn["middlewareData"];
  variant?: CoreTooltipProps["variant"];
  styleSlots?: CoreTooltipProps["styleSlots"];
}

export const TooltipContext = createContext<TooltipContextValue | null>(null);

export const useTooltipContext = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error("useTooltipContext must be used within a TooltipProvider");
  }
  return context;
};

export const useTooltip = (tooltipOptions: UseTooltipOptions): TooltipContextValue => {
  const {
    position = "top",
    enterDelay = 0,
    leaveDelay = 0,
    open: controlledOpen,
    onOpenChange,
    showOnHover = true,
    offset,
    arrow: arrowEnabled = true,
    variant = "default",
    styleSlots,
  } = tooltipOptions;

  const arrowRef = useRef(null);
  const [internalOpen, setInternalOpen] = useState(controlledOpen ?? false);
  const currentOpenState = controlledOpen ?? internalOpen;

  useEffect(() => {
    if (typeof controlledOpen === "boolean") {
      if (controlledOpen !== internalOpen) {
        setInternalOpen(controlledOpen);
        onOpenChange?.(controlledOpen);
      }
    }
  }, [controlledOpen, internalOpen, onOpenChange]);

  const {
    refs,
    floatingStyles,
    context,
    placement: actualPlacement,
    middlewareData,
  } = useFloating({
    open: currentOpenState,
    onOpenChange: (newOpenState) => {
      if (isNullish(controlledOpen)) {
        setInternalOpen(newOpenState);
      }
      onOpenChange?.(newOpenState);
    },
    placement: position,
    whileElementsMounted: autoUpdate,
    middleware: [
      floatingOffset(offset),
      flip(),
      shift(),
      hide(),
      arrow({
        element: arrowRef,
      }),
    ],
  });

  const hover = useHover(context, {
    delay: { open: enterDelay, close: leaveDelay },
    enabled: isNullish(controlledOpen) && showOnHover,
    move: false,
  });
  const focus = useFocus(context, {
    enabled: isNullish(controlledOpen),
  });
  const dismiss = useDismiss(context, {
    enabled: isNullish(controlledOpen),
  });

  const role = useRole(context, { role: "tooltip" });

  const interactions = [];
  if (isNullish(controlledOpen)) {
    if (showOnHover) {
      interactions.push(hover);
    }
    interactions.push(focus);
    interactions.push(dismiss);
  }
  interactions.push(role);

  const { getReferenceProps, getFloatingProps } = useInteractions(interactions);

  const duration = 250;
  const { isMounted, styles } = useTransitionStyles(context, {
    duration,
    initial: {
      opacity: 0,
    },
  });

  return {
    refs,
    floatingStyles,
    floatingContext: context,
    arrowRef,
    getReferenceProps,
    getFloatingProps,
    isMounted,
    styles,
    currentOpenState,
    actualPlacement,
    showArrow: arrowEnabled,
    middlewareData,
    variant,
    styleSlots,
  };
};
